WITH RecentShipments AS (SELECT * FROM shipments WHERE cost IS NOT NULL AND delivered_date < '2025-08-11'), shipped_year_summary AS (SELECT YEAR(shipped_date) AS shipped_year, COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) AS returned_count, COUNT(CASE WHEN carrier = 'UPS' THEN 1 END) AS ups_count FROM RecentShipments GROUP BY YEAR(shipped_date)) SELECT shipped_year, returned_count, ups_count FROM shipped_year_summary WHERE ups_count >= 3 ORDER BY ups_count DESC;
